 try:
  with warnings.catch_warnings():
   warnings.simplefilter('ignore')
   left=value(lib,a,'scalar' if mode in ['left_scalar','both_scalar'] else 'vector');right=value(lib,b,'scalar' if mode in ['right_scalar','both_scalar'] else 'vector')
   if op=='where':out=lib.where(lib.tensor([True,False]),left,right)
