   else:out=getattr(lib,op)([left,right])
   dt=str(out.dtype).removeprefix('torch.');data=out.to(lib.complex64).numpy() if dt=='complex32' else out.numpy();return {'dtype':dt,'shape':list(data.shape),'values':repr(data.tolist())}
