 for a,b in itertools.product(DT,repeat=2):
  for mode in modes:
   x,y=run(native,op,a,b,mode),run(torch,op,a,b,mode);match=(x==y) if 'error' not in x and 'error' not in y else x.get('error')==y.get('error')
   rows.append({'op':op,'left':a,'right':b,'mode':mode,'native':x,'adapter':y,'matches':match})
source=pathlib.Path(paperleet_torch.__file__).parent
out={'numpy':np.__version__,'native_torch':native.__version__,'library':paperleet_torch.__version__,'source_hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in source.glob('*.py')},'cases':rows}
